grep -n "call   3bb3\|call   3e8c\|call   3f1f\|call   3fb5" /tmp/bb.dis | sed 's/:/ /' | awk '{print strtonum("0x"$2)}' 2>/dev/null || grep -n "call   3bb3\|call   3e8c\|call   3f1f\|call   3fb5" /tmp/bb.dis | python3 -c "
import sys,re
for L in sys.stdin:
    m=re.match(r'(\d+):\s+([0-9a-f]+):',L)
    if m: print(int(m.group(2),16), L.split('call')[1].split('<')[0].strip())
" | sort -n | awk '{printf \"%x %s\n\", $1, $2}' | head -50

